#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#include <roapi.h>
#include "extension_runtime_directory.h"
#include <iostream>
using namespace moon::extension;using namespace winrt::Windows::Data::Json;
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}template<class F>void rejects(F f){bool rejected=false;try{f();}catch(...){rejected=true;}check(rejected,"Expected rejection");}
int main(int argc,char** argv){RoInitialize(RO_INIT_MULTITHREADED);try{
 auto dir=std::filesystem::path(argv[1])/("directory-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));std::filesystem::create_directories(dir/"com.example");auto write=[&](const std::filesystem::path& path,const std::string& value){std::ofstream out(path,std::ios::binary);out<<value;check(bool(out),"Fixture write");};
 auto manifest=JsonObject::Parse(L"{\"schemaVersion\":2,\"apiVersion\":\"1.0.0\",\"id\":\"com.example\",\"name\":\"Example\",\"version\":\"1\",\"unknownMetadata\":{\"preserve\":true},\"runtime\":{\"entry\":\"runtime.HTML\",\"permissions\":[\"runtime\",\"resources\"],\"resources\":{\"data\":\"data.bin\"}}}");auto save=[&](const JsonObject& m){write(dir/"com.example"/"manifest.json",winrt::to_string(m.Stringify()));};save(manifest);write(dir/"com.example"/"data.bin","abc");
 auto candidate=RuntimeDirectory::inspect(dir,"com.example");check(candidate.enabled&&candidate.extension.id=="com.example"&&candidate.entry=="runtime.HTML"&&candidate.permissions==std::vector<std::string>{"runtime","resources"}&&candidate.resources->read("data")==FileDropRouter::Bytes{'a','b','c'}&&candidate.manifest.GetNamedObject(L"unknownMetadata").GetNamedBoolean(L"preserve"),"Directory candidate lossless/runtime");
 write(dir/".state.json","{\"enabled\":{\"com.example\":false}}");check(!RuntimeDirectory::inspect(dir,"com.example").enabled,"Disabled state");write(dir/".state.json","{}");check(RuntimeDirectory::inspect(dir,"com.example").enabled,"Default enabled");write(dir/".state.json","{\"enabled\":{\"other\":4}}");rejects([&]{RuntimeDirectory::inspect(dir,"com.example");});write(dir/".state.json","{}");
 for(const auto& invalid:std::vector<std::string>{"../com.example",".hidden","a..b","a/b",std::string(81,'a')})rejects([&]{RuntimeDirectory::inspect(dir,invalid);});
 for(int scenario=0;scenario<7;++scenario){auto m=JsonObject::Parse(manifest.Stringify());auto runtime=m.GetNamedObject(L"runtime");if(scenario==0)m.Insert(L"id",JsonValue::CreateStringValue(L"other"));if(scenario==1)m.Insert(L"schemaVersion",JsonValue::CreateNumberValue(1));if(scenario==2)m.Insert(L"apiVersion",JsonValue::CreateStringValue(L"2.0.0"));if(scenario==3)runtime.Insert(L"entry",JsonValue::CreateStringValue(L"../runtime.html"));if(scenario==4)runtime.Insert(L"entry",JsonValue::CreateStringValue(L"runtime.lua"));if(scenario==5)runtime.Insert(L"permissions",JsonArray::Parse(L"[\"runtime\",\"runtime\"]"));if(scenario==6)runtime.Insert(L"permissions",JsonArray::Parse(L"[\"unknown\"]"));save(m);rejects([&]{RuntimeDirectory::inspect(dir,"com.example");});}save(manifest);
 write(dir/"com.example"/"manifest.json",std::string(256*1024+1,' '));rejects([&]{RuntimeDirectory::inspect(dir,"com.example");});save(manifest);
 auto commands=JsonArray::Parse(L"[{\"id\":\"lua\",\"name\":\"Lua\",\"entry\":\"脚本.LUA\",\"runtimeEvent\":null},{\"id\":\"event\",\"name\":\"Event\",\"description\":\"details\",\"entry\":null,\"runtimeEvent\":\"go\"},{\"id\":\"settings\",\"name\":\"Settings\",\"opensSettings\":true}]");
 auto full=JsonObject::Parse(manifest.Stringify());full.Insert(L"commands",commands);full.Insert(L"settingsUi",JsonObject{});full.GetNamedObject(L"runtime").GetNamedArray(L"permissions").Append(JsonValue::CreateStringValue(L"commands"));save(full);candidate=RuntimeDirectory::inspect(dir,"com.example");
 check(candidate.commands.size()==3&&candidate.commands[0].runtime.handler=="lua"&&candidate.commands[0].luaEntry==winrt::to_string(L"脚本.LUA")&&candidate.commands[0].description.empty()&&!candidate.commands[0].runtime.opensSettings&&candidate.commands[1].description=="details"&&candidate.commands[1].runtime.runtimeEvent=="go"&&candidate.commands[2].runtime.handler=="settings"&&candidate.extension.hasSettings,"Command metadata/defaults/handlers");
 check(inspectCommands(manifest,{}).empty(),"Absent commands default");
 auto one=[&](const JsonObject& c){auto m=JsonObject::Parse(full.Stringify());JsonArray a;a.Append(c);m.Insert(L"commands",a);return m;};
 auto lua=commands.GetAt(0).GetObject();auto stringValue=[](const std::string& v){return JsonValue::CreateStringValue(winrt::to_hstring(v));};
 for(const auto& field:std::vector<std::wstring>{L"id",L"name",L"description",L"entry",L"runtimeEvent",L"opensSettings"}){auto c=JsonObject::Parse(lua.Stringify());c.Insert(field,JsonValue::CreateNumberValue(1));rejects([&]{inspectCommands(one(c),candidate.permissions);});}
 for(const auto& id:std::vector<std::string>{"",".bad","a..b","bad/id",std::string(81,'a')}){auto c=JsonObject::Parse(lua.Stringify());c.Insert(L"id",stringValue(id));rejects([&]{inspectCommands(one(c),candidate.permissions);});}
 for(const auto& name:std::vector<std::string>{"","   ",winrt::to_string(L"　"),"bad\n",std::string(161,'a'),winrt::to_string(std::wstring(54,L'中'))}){auto c=JsonObject::Parse(lua.Stringify());c.Insert(L"name",stringValue(name));rejects([&]{inspectCommands(one(c),candidate.permissions);});}
 for(const auto& desc:std::vector<std::string>{std::string(4097,'a'),"bad\t",winrt::to_string(L"bad\u0085")}){auto c=JsonObject::Parse(lua.Stringify());c.Insert(L"description",stringValue(desc));rejects([&]{inspectCommands(one(c),candidate.permissions);});}
 auto boundary=JsonObject::Parse(lua.Stringify());boundary.Insert(L"name",stringValue(std::string(160,'a')));boundary.Insert(L"description",stringValue(std::string(4096,'a')));check(inspectCommands(one(boundary),candidate.permissions).size()==1,"Text limits inclusive");
 for(const auto& path:std::vector<std::string>{"../a.lua","manifest.json","a.txt","a\\b.lua","CON.lua"}){auto c=JsonObject::Parse(lua.Stringify());c.Insert(L"entry",stringValue(path));rejects([&]{inspectCommands(one(c),candidate.permissions);});}
 for(int scenario=0;scenario<8;++scenario){auto m=JsonObject::Parse(full.Stringify());auto a=m.GetNamedArray(L"commands");if(scenario==0)a.GetAt(0).GetObject().Remove(L"entry");if(scenario==1)a.GetAt(0).GetObject().Insert(L"opensSettings",JsonValue::CreateBooleanValue(true));if(scenario==2)a.GetAt(1).GetObject().Insert(L"id",stringValue("LUA"));if(scenario==3)m.Remove(L"runtime");if(scenario==4)a.GetAt(1).GetObject().Insert(L"runtimeEvent",stringValue("bad/event"));if(scenario==5)m.Remove(L"settingsUi");if(scenario==6)m.Insert(L"settingsUi",JsonValue::CreateNullValue());if(scenario==7)m.Insert(L"commands",JsonValue::CreateNullValue());rejects([&]{inspectCommands(m,candidate.permissions);});}
 rejects([&]{inspectCommands(full,{"runtime"});});
 auto many=JsonObject::Parse(full.Stringify());JsonArray a;for(int i=0;i<64;++i){auto c=JsonObject::Parse(lua.Stringify());c.Insert(L"id",stringValue("c"+std::to_string(i)));a.Append(c);}many.Insert(L"commands",a);check(inspectCommands(many,candidate.permissions).size()==64,"64 commands inclusive");auto extra=JsonObject::Parse(lua.Stringify());extra.Insert(L"id",stringValue("extra"));a.Append(extra);rejects([&]{inspectCommands(many,candidate.permissions);});
 auto noSettings=JsonObject::Parse(manifest.Stringify());noSettings.Insert(L"settingsEntry",JsonValue::CreateNullValue());noSettings.Insert(L"settingsUi",JsonValue::CreateNullValue());save(noSettings);check(!RuntimeDirectory::inspect(dir,"com.example").extension.hasSettings,"Null settings absent");
 std::cout<<"Installed directory candidate, state, lossless manifest and runtime validation passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}catch(const winrt::hresult_error& e){std::cerr<<winrt::to_string(e.message())<<'\n';return 1;}}
